package vn.iotstar.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import vn.iotstar.dto.*; import vn.iotstar.service.AuthService;
@Controller @RequiredArgsConstructor public class AuthController{final AuthService auth;@GetMapping("/login")String login(){return "auth/login";}@GetMapping("/register")String reg(Model m){m.addAttribute("form",new RegisterDTO());return "auth/register";}@PostMapping("/register")String reg(@Valid @ModelAttribute("form")RegisterDTO d,BindingResult b,Model m){if(b.hasErrors())return "auth/register";try{auth.register(d);return "redirect:/verify-otp?email="+d.getEmail();}catch(IllegalArgumentException e){m.addAttribute("error",e.getMessage());return "auth/register";}}@GetMapping("/verify-otp")String verify(@RequestParam String email,Model m){m.addAttribute("email",email);return "auth/verify-otp";}@PostMapping("/verify-otp")String verify(@RequestParam String email,@RequestParam String code,Model m){try{auth.verify(email,code);return "redirect:/login?verified=true";}catch(Exception e){m.addAttribute("email",email);m.addAttribute("error",e.getMessage());return "auth/verify-otp";}}@PostMapping("/resend-otp")String resend(@RequestParam String email){auth.resend(email);return "redirect:/verify-otp?email="+email;}@GetMapping("/forgot-password")String forgot(){return "auth/forgot-password";}@PostMapping("/forgot-password")String forgot(@RequestParam String email){auth.resetRequest(email);return "redirect:/reset-password?email="+email;}@GetMapping("/reset-password")String reset(@RequestParam String email,Model m){m.addAttribute("email",email);m.addAttribute("form",new ResetPasswordDTO());return "auth/reset-password";}@PostMapping("/reset-password")String reset(@RequestParam String email,@RequestParam String code,@Valid @ModelAttribute("form")ResetPasswordDTO d,BindingResult b,Model m){if(b.hasErrors()){m.addAttribute("email",email);return "auth/reset-password";}try{auth.reset(email,code,d);return "redirect:/login?reset=true";}catch(Exception e){m.addAttribute("email",email);m.addAttribute("error",e.getMessage());return "auth/reset-password";}}@GetMapping("/access-denied")String denied(){return "error/403";}}
